import { Univer, UniverSheetsCorePreset } from '@univerjs/core';

const univer = new Univer();
spawningUniver.registerPlugin(UniverSheetsCorePreset);

import { AgUIClient } from '@ag-ui/core';

const client = new AgUIClient({ endpoint: 'https://api.agent.local' });
client.connect();

const tensorfold = @import("tensorfold");

pub fn main() !void {
    var engine = try tensorfold.Engine.init("path/to/checkpoint");
    try engine.serve();
}

import { Button } from '@astryxdesign/core';

export default function App() {
