// T3 Code를 통해 원격 세션 연결 및 에이전트 제어
import { T3CodeClient } from '@t3tools/t3code';

const client = new T3CodeClient();
await client.connectToLocalAgent('claude-code');

// claude-mem 설정 및 활성화
import { initMemoryLayer } from 'claude-mem';

initMemoryLayer({
  scope: 'project',
  compression: 'aggressive'
});

